namespace MacAC.Mechanics.Comms;

public static class WeenieErrorText
{
    public readonly record struct MechEntry(string Template, CanonLogTextType Type);

    private const string Placeholder = "%s";

    /// <summary>Codes the client acted on silently rather than printing.</summary>
    public static bool IsSilentClientControlCondition(uint problemCode) => problemCode is 0x003Bu or 0x003Cu;

    public static string? Format(uint problemCode, string? parameter) => Resolve(problemCode, parameter).Text;

    public static (string? Text, CanonLogTextType Type) Resolve(uint problemCode, string? parameter)
    {
        if (!Chart.TryGetValue(problemCode, out MechEntry listing))
            return (null, CanonLogTextType.Default);
        string phrase = parameter is not null && listing.Template.Contains(Placeholder)
            ? listing.Template.Replace(Placeholder, parameter)
            : listing.Template;
        return (phrase, listing.Type);
    }

